using System;
using System.Threading.Tasks; using Microsoft.AspNetCore.Builder; using Microsoft.AspNetCore.Http; using Microsoft.AspNetCore.Routing; using Microsoft.eShopWeb.ApplicationCore.Services; using MinimalApi.Endpoint;  namespace Microsoft.eShopWeb.PublicApi.SubscriptionEndpoints;  public class CreateSubscriptionEndpoint : IEndpoint<IResult, CreateSubscriptionRequest> {     private readonly IMaxioClient _maxio;     private readonly MaxioSettings _settings;     private readonly ISubscriptionMappingService _map;     private readonly IHttpContextAccessor _httpAccessor;      public CreateSubscriptionEndpoint(IMaxioClient maxio, MaxioSettings settings, ISubscriptionMappingService map, IHttpContextAccessor httpAccessor)     {         _maxio = maxio;         _settings = settings;         _map = map;         _httpAccessor = httpAccessor;     }      public void AddRoute(IEndpointRouteBuilder app)     {         app.MapPost("api/subscriptions",             async (CreateSubscriptionRequest req) => await HandleAsync(req))             .Produces<CreateSubscriptionResponse>()             .WithTags("SubscriptionEndpoints")             .RequireAuthorization();     }      public async Task<IResult> HandleAsync(CreateSubscriptionRequest request)     {         var response = new CreateSubscriptionResponse(request.CorrelationId());         var user = _httpAccessor.HttpContext?.User;         var userId = user?.Identity?.Name ?? user?.FindFirst("sub")?.Value ?? "unknown";          try         {             var reference = _map.GetCustomerReference(userId);             if (string.IsNullOrEmpty(reference))             {                 var email = user?.FindFirst(System.Security.Claims.ClaimTypes.Email)?.Value ?? $"{userId}@eshop.local";                 var existing = await _maxio.FindCustomerByReferenceAsync(userId);                 if (existing == null)                 {                     var created = await _maxio.CreateCustomerAsync(new MaxioCustomerCreateRequest(userId, email, "User", ""));                     reference = created.Reference ?? userId;                 }                 else                 {                     reference = existing.Reference ?? userId;                 }                 _map.SetCustomerReference(userId, reference);             }              var sub = await _maxio.CreateSubscriptionAsync(new MaxioSubscriptionCreateRequest(reference, request.PlanHandle));             _map.SetSubscriptionId(userId, sub.Id.ToString());              response.SubscriptionId = sub.Id;             response.PlanHandle = sub.ProductHandle;             response.State = sub.State;             response.PriceMonthly = sub.PriceInCents;             response.NextBillingDate = sub.NextBillingDate;         }         catch (Exception ex)         {             return Results.BadRequest(new { error = "Subscription failed: " + ex.Message });         }         return Results.Ok(response);     } }
